package com.example.starter.incident;

import java.time.Instant;

/**
 * 事件实体，对应 incidents 表。
 * commander 为当前指挥人（X-Actor-Id），仅 REPORTED 状态为空；
 * 时间均为 UTC 秒级以上的 Instant。
 */
public record Incident(
        long id,
        String incidentKey,
        String severity,
        String summary,
        String reporter,
        IncidentStatus status,
        String commander,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 处置记录实体，对应 incident_actions 表。
 * occurredAt 为客户端上报的处置发生 UTC 时间；createdAt 为服务端落库 UTC 时间。
 * (incidentId, actionKey) 唯一，同键同内容幂等，同键不同内容冲突。
 */
public record IncidentAction(
        long id,
        long incidentId,
        String actionKey,
        String actionType,
        String note,
        Instant occurredAt,
        String actor,
        Instant createdAt) {

    /**
     * 判断两条记录的业务内容是否一致（用于 actionKey 幂等比对）。
     */
    public boolean sameContent(String actionType, String note, Instant occurredAt) {
        return this.actionType.equals(actionType)
                && this.note.equals(note)
                && this.occurredAt.equals(occurredAt);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 指挥交接单实体，对应 incident_transfers 表。
 * acceptedAt 仅 ACCEPTED 状态有值，其余为 null。
 */
public record IncidentTransfer(
        long id,
        long incidentId,
        String fromCommander,
        String toCommander,
        TransferStatus status,
        Instant createdAt,
        Instant acceptedAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 状态流转历史实体，对应 incident_status_history 表。
 * fromStatus 在事件创建（首次落库）时为 null；occurredAt 为 UTC 时间。
 */
public record StatusChange(
        long id,
        long incidentId,
        IncidentStatus fromStatus,
        IncidentStatus toStatus,
        String actor,
        Instant occurredAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 命令幂等键实体，对应 command_keys 表。
 * requestHash 为请求规范化参数的摘要；responseBody 为首次成功响应的 JSON，
 * 用于同键同参重放；responseStatus/responseBody 在事务提交前必定写入。
 */
public record CommandKeyRecord(
        long id,
        String commandKey,
        String operation,
        String requestHash,
        Integer responseStatus,
        String responseBody,
        Instant createdAt) {
}

